def transform(grid):
    h, w = len(grid), len(grid[0])
    from collections import Counter
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]

    # Full uniform rows/columns of a non-background color are separators.
    sep_rows = [r for r in range(h) if len(set(grid[r])) == 1 and grid[r][0] != bg]
    sep_cols = [c for c in range(w) if len({grid[r][c] for r in range(h)}) == 1 and grid[0][c] != bg]

    row_bounds = [-1] + sep_rows + [h]
    col_bounds = [-1] + sep_cols + [w]
    row_blocks = [(row_bounds[i] + 1, row_bounds[i + 1]) for i in range(len(row_bounds) - 1)]
    col_blocks = [(col_bounds[i] + 1, col_bounds[i + 1]) for i in range(len(col_bounds) - 1)]

    out = [row[:] for row in grid]
    template = None
    for r0, r1 in row_blocks:
        for c0, c1 in col_blocks:
            block = [row[c0:c1] for row in grid[r0:r1]]
            if any(v != bg for row in block for v in row):
                template = block
                break
        if template is not None:
            break

    if template is None:
        return out

    for r0, r1 in row_blocks:
        for c0, c1 in col_blocks:
            if r1 - r0 != len(template) or c1 - c0 != len(template[0]):
                continue
            for i in range(len(template)):
                for j in range(len(template[0])):
                    out[r0 + i][c0 + j] = template[i][j]
    return out
